import{_ as e,o as i,c as a,a2 as s}from"./chunks/framework.C8nVztS1.js";const p=JSON.parse('{"title":"Perf calibration","description":"Why the default load duration is 5s — measured rank stability vs longer runs.","frontmatter":{"title":"Perf calibration","description":"Why the default load duration is 5s — measured rank stability vs longer runs.","outline":"deep"},"headers":[],"relativePath":"guide/perf-calibration.md","filePath":"guide/perf-calibration.md","lastUpdated":1789877760000}'),r={name:"guide/perf-calibration.md"};function n(o,t,l,d,h,g){return i(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="perf-calibration" tabindex="-1">Perf calibration <a class="header-anchor" href="#perf-calibration" aria-label="Permalink to &quot;Perf calibration&quot;">​</a></h1><p>Question: does hammering a fixture for 10–60s change <strong>ranking</strong> vs a short autocannon run?</p><p>Measured on existing <code>nuxt-i18n-next</code> fixture builds (<code>plain-nuxt</code> / <code>i18n</code> / <code>i18n-micro</code>), same machine, sequential loads:</p><table tabindex="0"><thead><tr><th>Fixture</th><th style="text-align:right;">autocannon 5s RPS</th><th style="text-align:right;">autocannon 10s RPS</th><th style="text-align:right;">Δ</th><th style="text-align:right;">Artillery 2s+8s RPS</th></tr></thead><tbody><tr><td>plain-nuxt</td><td style="text-align:right;">64.0</td><td style="text-align:right;">65.2</td><td style="text-align:right;">1.9%</td><td style="text-align:right;">68</td></tr><tr><td>i18n</td><td style="text-align:right;">98.8</td><td style="text-align:right;">97.1</td><td style="text-align:right;">1.7%</td><td style="text-align:right;">100</td></tr><tr><td>i18n-micro</td><td style="text-align:right;">173.8</td><td style="text-align:right;">187.4</td><td style="text-align:right;">7.3%</td><td style="text-align:right;">112</td></tr></tbody></table><p><strong>Rank</strong> <code>micro &gt; i18n &gt; plain</code> holds for 5s and 10s.</p><p><strong>micro/i18n ratio:</strong> 1.76 (5s) vs 1.93 (10s) — relative gap change ≈ 9% (under the 15% budget). Absolute RPS for a single fixture still jitters; use the same duration every time and compare ratios/ranks, not one-off absolutes against an old report.</p><p>Published long Artillery (6s+60s) historically showed the same rank with a larger micro/i18n gap (~1.69 Artillery RPS). Short Artillery was noisier on absolute micro RPS in this pass — so the <strong>single default</strong> is autocannon <strong>10 connections × 5 seconds</strong>, not a separate “quick” profile.</p><p>Reproduce:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/perf-calibrate.ts</span></span></code></pre></div><p>Artifact: <code>.untestutils/perf-calibrate/calibration.json</code>.</p>',10)])])}const u=e(r,[["render",n]]);export{p as __pageData,u as default};
